    e.pop("_ZO_DATA_DIR",None); e.pop("_ZO_ECHO",None); e.pop("_ZO_EXCLUDE_DIRS",None); e.pop("_ZO_MAXAGE",None); e.pop("_ZO_RESOLVE_SYMLINKS",None); e.pop("_ZO_FZF_OPTS",None)
