import subprocess, os, tempfile, shutil, pathlib, time
EXE="/workspace/executable"
def run(args, env=None, cwd=None):
    e=dict(os.environ)
    for k in list(e):
        if k.startswith("_ZO"): del e[k]
    if env: e.update(env)
    return subprocess.run([EXE]+args, capture_output=True, text=True, env=e, cwd=cwd)

# DB test harness
tmp=tempfile.mkdtemp(prefix="zodb_")
print("tmp",tmp)
data=os.path.join(tmp,"data")
env={"_ZO_DATA_DIR":data, "HOME":tmp}  # HOME to affect exclude? default exclude is $HOME
# create dirs
for d in ["foo","bar","foo_bar","foobar","a/b/c"]:
    os.makedirs(os.path.join(tmp,d), exist_ok=True)

def show(args, env2=None):
    ee=dict(env)
    if env2: ee.update(env2)
    r=run(args, ee)
    print(args, "exit",r.returncode,"out",repr(r.stdout),"err",repr(r.stderr))
    # list data dir
    if os.path.exists(data):
        for root,dirs,files in os.walk(data):
            for f in files:
                p=os.path.join(root,f)
                print(" file",p, os.path.getsize(p))
                try:
                    print(pathlib.Path(p).read_bytes()[:2000])
                except Exception as e: print(e)
    print("---")
    return r

show(["add", os.path.join(tmp,"foo")])
show(["add", os.path.join(tmp,"foo")])
show(["add", os.path.join(tmp,"bar")])
show(["query","foo"])
show(["query","--list","foo"])
show(["query","--list","--score","foo"])
show(["query","--list"])
show(["query"])
show(["query","nonexistent_xyz"])

PY"}

