import subprocess, os, tempfile, struct, time, pathlib
EXE="/workspace/executable"
def run(args, env):
    e=dict(os.environ)
    for k in list(e):
        if k.startswith("_ZO"): del e[k]
    e.update(env)
    return subprocess.run([EXE]+args, capture_output=True, text=True, env=e)
def write_db(data_dir, entries):
    os.makedirs(data_dir, exist_ok=True)
    out=struct.pack("<I",3)+struct.pack("<Q", len(entries))
    for p,rank,ts in entries:
        if isinstance(p,str): p=p.encode()
        out+=struct.pack("<Q",len(p))+p+struct.pack("<d",rank)+struct.pack("<Q",ts)
    pathlib.Path(os.path.join(data_dir,"db.zo")).write_bytes(out)

tmp=tempfile.mkdtemp(prefix="zo_")
data=os.path.join(tmp,"data"); env={"HOME":tmp,"_ZO_DATA_DIR":data}
now=int(time.time())
paths=["/tmp/foo","/tmp/bar/foo","/foo/bar","/foo/bar/baz","/tmp/FooBar","/tmp/foo/bar","/a/b/c","/tmp/foofoo","/xyz/foo/bar/qux"]
write_db(data, [(p,1.0,now) for p in paths])
def q(*kws):
    r=run(["query","--list","--all"]+list(kws),env)
    print(f"q {kws} -> exit{r.returncode} out={r.stdout!r} err={r.stderr!r}")
for kw in [["foo"],["bar"],["tmp"],["tmp","foo"],["foo","bar"],["bar","foo"],["foo","baz"],["baz"],["a","b"],["a","c"],["b","c"],["c"],["a","b","c"],["FOO"],["FooBar"],["foobar"],["oo"],["/tmp"],["tmp/foo"],["foo/bar"],["/"],["qux"],["xyz","qux"],["xyz","bar","qux"]]:
    q(*kw)

# Empty keyword? ""
q("")
q(" ")
# keyword with slash at end
q("foo/")
q("foo/b")
