import subprocess, os, tempfile, pathlib, struct
EXE="/workspace/executable"
def run(args, env):
    e=dict(os.environ)
    for k in list(e):
        if k.startswith("_ZO"): del e[k]
    e.update(env)
    return subprocess.run([EXE]+args, capture_output=True, text=True, env=e)
tmp=tempfile.mkdtemp(prefix="zo_")
os.makedirs(os.path.join(tmp,"foo")); os.makedirs(os.path.join(tmp,"bar"))
env={"HOME":tmp,"_ZO_DATA_DIR":os.path.join(tmp,"data")}
for args in [["edit","reload","--version"],["edit","delete","--version"],["edit","--version"],["edit","increment","-V"]]:
    r=run(args,env); print(args, r.returncode, repr(r.stdout), repr(r.stderr))
# Setup DB
run(["add",tmp+"/foo"],env); run(["add",tmp+"/bar"],env); run(["add",tmp+"/bar"],env)
def db():
    p=os.path.join(tmp,"data","db.zo")
    d=pathlib.Path(p).read_bytes(); off=4; cnt=struct.unpack_from("<Q",d,off)[0]; off+=8; ents=[]
    for i in range(cnt):
        l=struct.unpack_from("<Q",d,off)[0]; off+=8; pp=d[off:off+l].decode(); off+=l; rank=struct.unpack_from("<d",d,off)[0]; off+=8; ts=struct.unpack_from("<Q",d,off)[0]; off+=8; ents.append((pp,rank,ts))
    return ents
print("db",db())
for args in [["edit","reload"],["query","--list","--score","--all"]]:
    r=run(args,env); print(args, r.returncode, repr(r.stdout), repr(r.stderr), "db", db())
# increment/decrement/delete operations
for cmd in ["increment","decrement","delete"]:
    for target in [tmp+"/foo", tmp+"/bar", "/nonexistent"]:
        r=run(["edit",cmd,target],env)
        print(f"edit {cmd} {target} -> {r.returncode} out={r.stdout!r} err={r.stderr!r} db={db()}")
    print("reload", repr(run(["edit","reload"],env).stdout))

PY"}

