use crate::util;
use anyhow::{anyhow, Context, Result};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Dir {
    pub path: String,
    pub rank: f64,
    pub last_accessed: u64,
}

impl Dir {
    pub fn get_score(&self, now: u64) -> f64 {
        let duration = now.saturating_sub(self.last_accessed);
        let factor = if duration < 3600 {
            4.0
        } else if duration < 86400 {
            2.0
        } else if duration < 604800 {
            0.5
        } else {
            0.25
        };
        self.rank * factor
    }
    pub fn display_score(&self, now: u64) -> String {
        let score = self.get_score(now).clamp(0.0, 9999.0);
        format!("{:>6.1}", score)
    }
}

pub struct Database {
    pub dirs: Vec<Dir>,
    pub data_dir: PathBuf,
    pub db_path: PathBuf,
    pub modified: bool,
}

impl Database {
    pub fn open() -> Result<Self> {
        let data_dir = util::get_data_dir()?;
        let _ = fs::create_dir_all(&data_dir);
        let db_path = data_dir.join("db.zo");
        let dirs = match fs::read(&db_path) {
            Ok(contents) => Self::deserialize(&contents)?,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
            Err(e) => {
                return Err(e).context(format!(
                    "could not read from database: {}",
                    db_path.display()
                ))
            }
        };
        Ok(Self {
            dirs,
            data_dir,
            db_path,
            modified: false,
        })
    }

    fn deserialize(bytes: &[u8]) -> Result<Vec<Dir>> {
        if bytes.len() < 4 {
            return Err(anyhow!("could not deserialize database: corrupted data"));
        }
        let version = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);
        if version != 3 {
            return Err(anyhow!(
                "unsupported version (got {}, supports 3)",
                version
            ));
        }
        // Deserialize body with bincode-like errors.
        let body_result = (|| -> std::result::Result<Vec<Dir>, anyhow::Error> {
            let mut offset: usize = 4;
            let read_u64 = |offset: &mut usize| -> std::result::Result<u64, anyhow::Error> {
                if bytes.len().saturating_sub(*offset) < 8 {
                    return Err(anyhow!("io error: unexpected end of file"));
                }
                let mut buf = [0u8; 8];
                buf.copy_from_slice(&bytes[*offset..*offset + 8]);
                *offset += 8;
                Ok(u64::from_le_bytes(buf))
            };
            let count = read_u64(&mut offset)?;
            let mut dirs = Vec::new();
            for _ in 0..count {
                let path_len = read_u64(&mut offset)?;
                // String bytes: bincode gives a different error if not enough bytes
                if (bytes.len().saturating_sub(offset) as u64) < path_len {
                    return Err(anyhow!("io error: "));
                }
                let path_len_usize = path_len as usize;
                let path_bytes = &bytes[offset..offset + path_len_usize];
                offset += path_len_usize;
                let path = match std::str::from_utf8(path_bytes) {
                    Ok(s) => s.to_string(),
                    Err(e) => {
                        return Err(anyhow!("string is not valid utf8: {}", e));
                    }
                };
                // rank f64
                if bytes.len().saturating_sub(offset) < 8 {
                    return Err(anyhow!("io error: unexpected end of file"));
                }
                let mut rbuf = [0u8; 8];
                rbuf.copy_from_slice(&bytes[offset..offset + 8]);
                offset += 8;
                let rank = f64::from_le_bytes(rbuf);
                let ts = read_u64(&mut offset)?;
                dirs.push(Dir {
                    path,
                    rank,
                    last_accessed: ts,
                });
            }
            if offset != bytes.len() {
                return Err(anyhow!("Slice had bytes remaining after deserialization"));
            }
            Ok(dirs)
        })();
        match body_result {
            Ok(dirs) => Ok(dirs),
            Err(e) => Err(e).context("could not deserialize database"),
        }
    }

    fn serialize(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(&3u32.to_le_bytes());
        out.extend_from_slice(&(self.dirs.len() as u64).to_le_bytes());
        for dir in &self.dirs {
            out.extend_from_slice(&(dir.path.len() as u64).to_le_bytes());
            out.extend_from_slice(dir.path.as_bytes());
            out.extend_from_slice(&dir.rank.to_le_bytes());
            out.extend_from_slice(&dir.last_accessed.to_le_bytes());
        }
        out
    }

    pub fn save(&mut self) -> Result<()> {
        if !self.modified {
            return Ok(());
        }
        let result = self.save_inner();
        if result.is_ok() {
            self.modified = false;
        }
        result
    }

    fn save_inner(&mut self) -> Result<()> {
        let bytes = self.serialize();
        // Generate a temporary filename: tmp_ + 12 alphanumeric chars
        let temp_name = format!("tmp_{}", random_alphanumeric_12());
        let temp_path = self.data_dir.join(&temp_name);
        let create_result = fs::File::create(&temp_path);
        let mut file = match create_result {
            Ok(f) => f,
            Err(e) => {
                return Err(e)
                    .context(format!("could not create file: {}", temp_path.display()))
                    .context("could not write to database");
            }
        };
        if let Err(e) = file.write_all(&bytes) {
            let _ = fs::remove_file(&temp_path);
            return Err(e).context("could not write to database");
        }
        // Ensure data is flushed before rename (File drop closes; explicit sync not required)
        drop(file);
        if let Err(e) = fs::rename(&temp_path, &self.db_path) {
            let _ = fs::remove_file(&temp_path);
            return Err(e).context("could not write to database");
        }
        Ok(())
    }

    pub fn sort_by_score(&mut self, now: u64) {
        self.dirs
            .sort_by(|a, b| a.get_score(now).total_cmp(&b.get_score(now)));
        self.modified = true;
    }

    pub fn sort_by_path(&mut self) {
        self.dirs.sort_by(|a, b| a.path.cmp(&b.path));
        self.modified = true;
    }

    pub fn remove_by_path(&mut self, path: &str) -> bool {
        if let Some(idx) = self.dirs.iter().position(|d| d.path == path) {
            self.dirs.swap_remove(idx);
            self.modified = true;
            true
        } else {
            false
        }
    }

    pub fn add_update(&mut self, path: &str, increment: f64, now: u64) {
        if let Some(dir) = self.dirs.iter_mut().find(|d| d.path == path) {
            dir.rank = (dir.rank + increment).max(0.0);
            dir.last_accessed = now;
        } else {
            self.dirs.push(Dir {
                path: path.to_string(),
                rank: increment.max(0.0),
                last_accessed: now,
            });
        }
        self.modified = true;
    }

    pub fn edit_update(&mut self, path: &str, increment: f64, now: u64) {
        if let Some(dir) = self.dirs.iter_mut().find(|d| d.path == path) {
            dir.rank = (dir.rank + increment).max(0.0);
            // last_accessed unchanged for existing entries
        } else {
            self.dirs.push(Dir {
                path: path.to_string(),
                rank: increment.max(0.0),
                last_accessed: now,
            });
        }
        self.modified = true;
    }

    pub fn age(&mut self, max_age: u32) {
        let total: f64 = self.dirs.iter().map(|d| d.rank).sum();
        if total > max_age as f64 {
            let factor = 0.9 * max_age as f64 / total;
            for dir in self.dirs.iter_mut() {
                dir.rank *= factor;
            }
            let mut idx = self.dirs.len();
            while idx > 0 {
                idx -= 1;
                if self.dirs[idx].rank < 1.0 {
                    self.dirs.swap_remove(idx);
                }
            }
            self.modified = true;
        }
    }
}

fn random_alphanumeric_12() -> String {
    // Simple xorshift seeded from time, pid and an atomic counter.
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    let mut state = now ^ (std::process::id() as u64).wrapping_mul(0x9e3779b97f4a7c15) ^ count.wrapping_mul(0xbf58476d1ce4e5b9) ^ 0x2545F4914F6CDD1D;
    if state == 0 { state = 0x12345678abcdef; }
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut s = String::with_capacity(12);
    for _ in 0..12 {
        // xorshift64*
        state ^= state >> 12;
        state ^= state << 25;
        state ^= state >> 27;
        let val = state.wrapping_mul(0x2545F4914F6CDD1D);
        s.push(CHARS[(val >> 59) as usize % 62] as char);
        // Use more bits for subsequent chars by continuing xorshift in loop; the above uses top bits
        // To add variety, also rotate state
        state = state.wrapping_add(0x9e3779b97f4a7c15);
    }
    s
}

pub fn _path_exists(p: &Path) -> bool { p.exists() }
RS"}

