use anyhow::{anyhow, Context, Result};
use std::io::{Read, Write};
use std::process::{Child, Command, Stdio};

pub struct Fzf {
    pub child: Child,
}

pub enum FzfStatus {
    Success,
    Exit130,
}

impl Fzf {
    pub fn spawn(args: &[&str], fzf_default_opts: Option<std::ffi::OsString>) -> Result<Self> {
        let mut cmd = Command::new("fzf");
        cmd.args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit());
        if let Some(v) = fzf_default_opts {
            cmd.env("FZF_DEFAULT_OPTS", v);
        }
        match cmd.spawn() {
            Ok(child) => Ok(Self { child }),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                Err(anyhow!("could not find fzf, is it installed?"))
            }
            Err(e) => Err(e).context("could not launch fzf"),
        }
    }

    pub fn write_input(&mut self, data: &[u8]) {
        if let Some(mut stdin) = self.child.stdin.take() {
            let _ = stdin.write_all(data);
            // drop closes stdin
        }
    }

    // Reads stdout to string, waits, classifies status.
    // Returns Ok(FzfStatus::Success) with selection string, or Exit130 marker.
    pub fn finish(mut self) -> Result<(FzfStatus, String)> {
        let mut selection = String::new();
        if let Some(mut stdout) = self.child.stdout.take() {
            stdout
                .read_to_string(&mut selection)
                .context("failed to read from fzf")?;
        }
        let status = match self.child.wait() {
            Ok(s) => s,
            Err(e) => return Err(e).context("failed to read from fzf"),
        };
        match status.code() {
            Some(0) => Ok((FzfStatus::Success, selection)),
            Some(1) => Err(anyhow!("no match found")),
            Some(2) => Err(anyhow!("fzf returned an error")),
            Some(130) => Ok((FzfStatus::Exit130, selection)),
            Some(code) if (128..255).contains(&code) => {
                Err(anyhow!("fzf was terminated"))
            }
            None => Err(anyhow!("fzf was terminated")),
            _ => Err(anyhow!("fzf returned an unknown error")),
        }
    }
}

