fn print_stdout(s: &str) {
    let mut out = std::io::stdout().lock();
    let _ = out.write_all(s.as_bytes());
    let _ = out.flush();
}

fn is_match(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }
    let path_lower = path.to_lowercase();
    let mut start: usize = 0;
    // all but last
    for kw in &keywords[..keywords.len() - 1] {
        let kw_lower = kw.to_lowercase();
        if kw_lower.is_empty() {
            continue;
        }
        match path_lower[start..].find(&kw_lower) {
            Some(rel) => {
                start = start + rel + kw_lower.len();
            }
            None => return false,
        }
    }
    let last_lower = keywords[keywords.len() - 1].to_lowercase();
    if last_lower.is_empty() {
        return true;
    }
    let last_sep: Option<usize> = path_lower.rfind('/');
    let mut search = start;
    loop {
        if search > path_lower.len() {
            return false;
        }
        let Some(rel) = path_lower[search..].find(&last_lower) else {
            return false;
        };
        let abs = search + rel;
        let end = abs + last_lower.len();
        let ok = match last_sep {
            Some(sep) => end > sep,
            None => true,
        };
        if ok {
            return true;
        }
        // Advance by one character from abs
        let next_char_len = path_lower[abs..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        search = abs + next_char_len;
    }
}

struct CandidateStream<'a> {
    db: &'a mut Database,
    next_idx: Option<usize>,
    keywords: Vec<String>,
    all: bool,
    exclude_arg: Option<String>,
    base_dir: Option<String>,
    exclude_globs: Vec<glob::Pattern>,
    now: u64,
}

impl<'a> CandidateStream<'a> {
    fn new(
        db: &'a mut Database,
        keywords: Vec<String>,
        all: bool,
        exclude_arg: Option<String>,
        base_dir: Option<String>,
        exclude_globs: Vec<glob::Pattern>,
        now: u64,
    ) -> Self {
        let next_idx = if db.dirs.is_empty() {
            None
        } else {
            Some(db.dirs.len() - 1)
        };
        Self {
            db,
            next_idx,
            keywords,
            all,
            exclude_arg,
            base_dir,
            exclude_globs,
            now,
        }
    }

    fn next_candidate(&mut self) -> Option<Dir> {
        while let Some(idx) = self.next_idx {
            self.next_idx = if idx == 0 { None } else { Some(idx - 1) };
            if idx >= self.db.dirs.len() {
                continue;
            }
            let entry = self.db.dirs[idx].clone();
            if !is_match(&entry.path, &self.keywords) {
                continue;
            }
            if let Some(base) = &self.base_dir {
                if !Path::new(&entry.path).starts_with(base) {
                    continue;
                }
            }
            if self.exclude_globs.iter().any(|p| p.matches(&entry.path)) {
                self.db.dirs.swap_remove(idx);
                self.db.modified = true;
                continue;
            }
            if let Some(excl) = &self.exclude_arg {
                if &entry.path == excl {
                    continue;
                }
            }
            if !self.all && !Path::new(&entry.path).is_dir() {
                continue;
            }
            return Some(entry);
        }
        None
    }
}

fn format_result(entry: &Dir, now: u64, with_score: bool) -> String {
    if with_score {
        format!("{} {}\n", entry.display_score(now), entry.path)
    } else {
        format!("{}\n", entry.path)
    }
}

fn run_add(matches: &clap::ArgMatches) -> Result<Flow> {
    // Parse env config before opening DB (order matters)
    let exclude_globs = util::get_exclude_globs()?;
    let max_age = util::get_max_age()?;
    let mut db = Database::open()?;
    let paths: Vec<PathBuf> = matches
        .get_many::<PathBuf>("PATHS")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let score = matches.get_one::<f64>("score").copied().unwrap_or(1.0);
    let resolve = util::env_is_one("_ZO_RESOLVE_SYMLINKS");
    let now = util::now_secs();
    for path in &paths {
        let resolved = util::resolve_path(path, resolve)?;
        let path_str = match resolved.to_str() {
            Some(s) => s.to_string(),
            None => {
                return Err(anyhow!(
                    "invalid unicode in path: {}",
                    resolved.display()
                ))
            }
        };
        if exclude_globs.iter().any(|p| p.matches(&path_str)) {
            continue;
        }
        if !Path::new(&path_str).is_dir() {
            return Err(anyhow!("not a directory: {}", path_str));
        }
        db.add_update(&path_str, score, now);
    }
    // Aging only if database was modified by adds above; if modified is false (all excluded), save is no-op anyway,
    // but aging should not be applied in that case. Check modified before age.
    if db.modified {
        db.age(max_age);
    }
    db.save()?;
    Ok(Flow::Normal)
}

fn run_remove(matches: &clap::ArgMatches) -> Result<Flow> {
    let mut db = Database::open()?;
    let paths: Vec<String> = matches
        .get_many::<String>("PATHS")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    for path in &paths {
        let resolved = util::resolve_path(Path::new(path), false)?;
        // resolved is derived from String, should be valid unicode; fall back to lossy if cwd is non-unicode
        let resolved_str = resolved.to_string_lossy().into_owned();
        if !db.remove_by_path(&resolved_str) {
            return Err(anyhow!("path not found in database: {}", path));
        }
    }
    db.save()?;
    Ok(Flow::Normal)
}

fn run_query(matches: &clap::ArgMatches) -> Result<Flow> {
    let mut db = Database::open()?;
    let exclude_globs = util::get_exclude_globs()?;
    let now = util::now_secs();
    db.sort_by_score(now);

    let keywords: Vec<String> = matches
        .get_many::<String>("KEYWORDS")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let all = matches.get_flag("all");
    let interactive = matches.get_flag("interactive");
    let list = matches.get_flag("list");
    let with_score = matches.get_flag("score");
    let exclude_arg = matches.get_one::<String>("exclude").cloned();
    let base_dir = matches.get_one::<String>("base-dir").cloned();

    if interactive {
        // Determine fzf args / opts
        let (args, fzf_env): (Vec<&str>, Option<std::ffi::OsString>) =
            match std::env::var_os("_ZO_FZF_OPTS") {
                Some(v) => (fzf::QUERY_FZF_MINIMAL_ARGS.to_vec(), Some(v)),
                None => (fzf::QUERY_FZF_DEFAULT_ARGS.to_vec(), None),
            };
        // Spawn fzf first (missing-fzf case should not consume/remove candidates)
        let mut fzf_proc = match fzf::Fzf::spawn(&args, fzf_env) {
            Ok(f) => f,
            Err(e) => {
                let _ = db.save();
                return Err(e);
            }
        };
        // Collect candidates and build fzf input
        let mut input = String::new();
        {
            let mut stream = CandidateStream::new(
                &mut db,
                keywords,
                all,
                exclude_arg,
                base_dir,
                exclude_globs,
                now,
            );
            while let Some(entry) = stream.next_candidate() {
                input.push_str(&format!(
                    "{}\t{}\0",
                    entry.display_score(now),
                    entry.path
                ));
            }
        }
        fzf_proc.write_input(input.as_bytes());
        // Finish fzf. On any error, persist removals/sorting silently before returning.
        let (status, selection) = match fzf_proc.finish() {
            Ok(v) => v,
            Err(e) => {
                let _ = db.save();
                return Err(e);
            }
        };
        match status {
            fzf::FzfStatus::Exit130 => {
                let _ = db.save();
                return Ok(Flow::Exit130);
            }
            fzf::FzfStatus::Success => {}
        }
        // Success: extract result
        let result = if with_score {
            selection.clone()
        } else {
            match selection.get(7..) {
                Some(s) => s.to_string(),
                None => {
                    let _ = db.save();
                    return Err(anyhow!("could not read selection from fzf"));
                }
            }
        };
        print_stdout(&result);
        db.save()?;
        Ok(Flow::Normal)
    } else if list {
        let mut output = String::new();
        {
            let mut stream = CandidateStream::new(
                &mut db,
                keywords,
                all,
                exclude_arg,
                base_dir,
                exclude_globs,
                now,
            );
            while let Some(entry) = stream.next_candidate() {
                output.push_str(&format_result(&entry, now, with_score));
            }
        }
        print_stdout(&output);
        db.save()?;
        Ok(Flow::Normal)
    } else {
        // Single result
        let candidate;
        {
            let mut stream = CandidateStream::new(
                &mut db,
                keywords,
                all,
                exclude_arg,
                base_dir,
                exclude_globs,
                now,
            );
            candidate = stream.next_candidate();
        }
        match candidate {
            Some(entry) => {
                let out = format_result(&entry, now, with_score);
                print_stdout(&out);
                db.save()?;
                Ok(Flow::Normal)
            }
            None => {
                let _ = db.save();
                Err(anyhow!("no match found"))
            }
        }
    }
}

fn reload_output(db: &Database, now: u64) -> String {
    let mut out = String::new();
    for entry in db.dirs.iter().rev() {
        out.push_str(&format!("{}\t{}\0", entry.display_score(now), entry.path));
    }
    out
}

fn run_edit(matches: &clap::ArgMatches) -> Result<Flow> {
    // Check hidden subcommands
    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        match sub_name {
            "reload" => {
                let db = Database::open()?;
                let now = util::now_secs();
                let out = reload_output(&db, now);
                print_stdout(&out);
                Ok(Flow::Normal)
            }
            "delete" => {
                let path = sub_matches.get_one::<String>("PATH").unwrap().clone();
                let mut db = Database::open()?;
                let now = util::now_secs();
                db.remove_by_path(&path);
                db.save()?;
                let out = reload_output(&db, now);
                print_stdout(&out);
                Ok(Flow::Normal)
            }
            "increment" => {
                let path = sub_matches.get_one::<String>("PATH").unwrap().clone();
                let mut db = Database::open()?;
                let now = util::now_secs();
                db.edit_update(&path, 1.0, now);
                db.save()?;
                let out = reload_output(&db, now);
                print_stdout(&out);
                Ok(Flow::Normal)
            }
            "decrement" => {
                let path = sub_matches.get_one::<String>("PATH").unwrap().clone();
                let mut db = Database::open()?;
                let now = util::now_secs();
                db.edit_update(&path, -1.0, now);
                db.save()?;
                let out = reload_output(&db, now);
                print_stdout(&out);
                Ok(Flow::Normal)
            }
            _ => unreachable!(),
        }
    } else {
        // Interactive edit UI
        let mut db = Database::open()?;
        let now = util::now_secs();
        db.sort_by_score(now);
        db.save()?;
        // spawn fzf with edit args, no FZF_OPTS translation
        let mut fzf_proc = fzf::Fzf::spawn(fzf::EDIT_FZF_ARGS, None)?;
        fzf_proc.write_input(b"");
        let (status, _selection) = fzf_proc.finish()?;
        match status {
            fzf::FzfStatus::Exit130 => Ok(Flow::Exit130),
            fzf::FzfStatus::Success => Ok(Flow::Normal),
        }
    }
}

fn sigmoid(x: f64) -> f64 {
    1.0 / (1.0 + (-x).exp())
}

fn parse_import(content: &str, from: &str) -> Result<Vec<Dir>> {
    let mut imported: Vec<Dir> = Vec::new();
    let mut add_imported = |entry: Dir, imported: &mut Vec<Dir>| {
        if let Some(existing) = imported.iter_mut().find(|d| d.path == entry.path) {
            existing.rank += entry.rank;
            if entry.last_accessed > existing.last_accessed {
                existing.last_accessed = entry.last_accessed;
            }
        } else {
            imported.push(entry);
        }
    };
    if from == "z" {
        for line in content.lines() {
            if line.is_empty() {
                continue;
            }
            let mut parts = line.rsplitn(3, '|');
            let epoch_str = parts.next().unwrap_or("");
            let epoch: u64 = epoch_str
                .parse()
                .with_context(|| format!("invalid epoch: {}", epoch_str))?;
            let rank_str = match parts.next() {
                Some(v) => v,
                None => return Err(anyhow!("invalid entry: {}", line)),
            };
            let rank: f64 = rank_str
                .parse()
                .with_context(|| format!("invalid rank: {}", rank_str))?;
            let path = match parts.next() {
                Some(v) => v,
                None => return Err(anyhow!("invalid entry: {}", line)),
            };
            add_imported(
                Dir {
                    path: path.to_string(),
                    rank,
                    last_accessed: epoch,
                },
                &mut imported,
            );
        }
    } else {
        // autojump
        for line in content.lines() {
            if line.is_empty() {
                continue;
            }
            let (rank_str, path) = match line.split_once('\t') {
                Some(v) => v,
                None => return Err(anyhow!("invalid entry: {}", line)),
            };
            let rank_raw: f64 = rank_str
                .parse()
                .with_context(|| format!("invalid rank: {}", rank_str))?;
            let rank = sigmoid(rank_raw);
            add_imported(
                Dir {
                    path: path.to_string(),
                    rank,
                    last_accessed: 0,
                },
                &mut imported,
            );
        }
    }
    Ok(imported)
}

fn run_import(matches: &clap::ArgMatches) -> Result<Flow> {
    let path = matches.get_one::<PathBuf>("PATH").unwrap().clone();
    let from = matches.get_one::<String>("from").unwrap().clone();
    let merge = matches.get_flag("merge");

    let content = std::fs::read_to_string(&path).map_err(|e| {
        anyhow::Error::from(e).context(format!(
            "could not open database for importing: {}",
            path.display()
        ))
    })?;

    let mut db = Database::open()?;
    if !merge && !db.dirs.is_empty() {
        return Err(anyhow!(
            "current database is not empty, specify --merge to continue anyway"
        ));
    }
    let imported = parse_import(&content, &from).context("import error")?;
    if imported.is_empty() {
        return Ok(Flow::Normal);
    }
    if merge {
        for entry in &imported {
            if let Some(existing) = db.dirs.iter_mut().find(|d| d.path == entry.path) {
                existing.rank += entry.rank;
                if entry.last_accessed > existing.last_accessed {
                    existing.last_accessed = entry.last_accessed;
                }
            } else {
                db.dirs.push(entry.clone());
            }
            db.modified = true;
        }
    } else {
        db.dirs = imported;
        db.modified = true;
    }
    db.sort_by_path();
    db.save()?;
    Ok(Flow::Normal)
}

fn run_init(matches: &clap::ArgMatches) -> Result<Flow> {
    let shell = matches.get_one::<String>("SHELL").unwrap().clone();
    let hook = matches.get_one::<String>("hook").unwrap().clone();
    let cmd = matches.get_one::<String>("cmd").unwrap().clone();
    let no_cmd = matches.get_flag("no-cmd");
    let echo = util::env_is_one("_ZO_ECHO");
    let resolve = util::env_is_one("_ZO_RESOLVE_SYMLINKS");
    let template = templates::get_template(&shell, &hook, echo, resolve, no_cmd);
    let output = if no_cmd {
        template.to_string()
    } else {
        template.replace("@@Z_CMD@@", &cmd)
    };
    print_stdout(&output);
    Ok(Flow::Normal)
}

fn run() -> Result<Flow> {
    let matches = main_cmd().get_matches();
    match matches.subcommand() {
        Some(("add", sub)) => run_add(sub),
        Some(("edit", sub)) => run_edit(sub),
        Some(("import", sub)) => run_import(sub),
        Some(("init", sub)) => run_init(sub),
        Some(("query", sub)) => run_query(sub),
        Some(("remove", sub)) => run_remove(sub),
        _ => unreachable!(),
    }
}

fn main() {
    let code = match run() {
        Ok(Flow::Normal) => 0,
        Ok(Flow::Exit130) => 130,
        Err(e) => {
            eprintln!("zoxide: {:?}", e);
            1
        }
    };
    std::process::exit(code);
}
